// Prepare a buffer with at least 1 byte and choose an offset to exercise unaligned access
std::string buf = FUZZ_PARAM_STR();
if (buf.size() < 1) buf.resize(1, '\0');
size_t off = (size_t)(*FUZZ_PARAM(unsigned int) % buf.size());

// Manually encode a random byte at little-endian order (trivial for 1 byte)
uint8_t val = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFFu);
reinterpret_cast<uint8_t*>(buf.data())[off] = val;

// Call target and assert round-trip correctness
const uint8_t *p = reinterpret_cast<const uint8_t*>(buf.data()) + off;
uint8_t got = le_to_u8(p);
FUZZ_ASSERT(got == val, "le_to_u8 failed to decode byte");

// Validation: ensures non-null buffer with >=1 byte and verifies decoded value matches the byte written.

// Need 2 bytes; pick unaligned offset within bounds
std::string buf = FUZZ_PARAM_STR();
size_t need = 2; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(unsigned int) % (buf.size() - need + 1));

// Random 16-bit value; encode little-endian manually
uint16_t v = (uint16_t)(*FUZZ_PARAM(unsigned int));
uint8_t *b = reinterpret_cast<uint8_t*>(buf.data());
b[off+0] = (uint8_t)(v & 0xFFu);
b[off+1] = (uint8_t)((v >> 8) & 0xFFu);

// Call target and assert
const uint8_t *p = reinterpret_cast<const uint8_t*>(buf.data()) + off;
uint16_t got = le_to_u16(p);
FUZZ_ASSERT(got == v, "le_to_u16 failed to decode");

// Validation: buffer is >=2 bytes; offset constrained; verifies exact round-trip.

// Need 4 bytes; select offset for possible unaligned read
std::string buf = FUZZ_PARAM_STR();
size_t need = 4; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(unsigned int) % (buf.size() - need + 1));

uint32_t v = *FUZZ_PARAM(uint32_t);
uint8_t *b = reinterpret_cast<uint8_t*>(buf.data());
b[off+0] = (uint8_t)( v        & 0xFFu);
b[off+1] = (uint8_t)((v >>  8) & 0xFFu);
b[off+2] = (uint8_t)((v >> 16) & 0xFFu);
b[off+3] = (uint8_t)((v >> 24) & 0xFFu);

const uint8_t *p = reinterpret_cast<const uint8_t*>(buf.data()) + off;
uint32_t got = le_to_u32(p);
FUZZ_ASSERT(got == v, "le_to_u32 failed to decode");

// Validation: meets size and alignment constraints; checks exact equality.

// Need 8 bytes; choose offset
std::string buf = FUZZ_PARAM_STR();
size_t need = 8; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(uint32_t) % (buf.size() - need + 1));

uint64_t v = *FUZZ_PARAM(uint64_t);
uint8_t *b = reinterpret_cast<uint8_t*>(buf.data());
for (int i = 0; i < 8; ++i) b[off+i] = (uint8_t)((v >> (8*i)) & 0xFFu);

const uint8_t *p = reinterpret_cast<const uint8_t*>(buf.data()) + off;
uint64_t got = le_to_u64(p);
FUZZ_ASSERT(got == v, "le_to_u64 failed to decode");

// Validation: ensures >=8 bytes, unaligned safe, and verifies round-trip.

// Need 2 writable bytes
std::string buf = FUZZ_PARAM_STR();
size_t need = 2; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(uint32_t) % (buf.size() - need + 1));

uint16_t v = (uint16_t)(*FUZZ_PARAM(unsigned int));
uint8_t *dst = reinterpret_cast<uint8_t*>(buf.data()) + off;

// Call target to write little-endian
u16_to_le(v, dst);

// Manually reconstruct and assert equality
uint16_t got = (uint16_t)( (uint16_t)dst[0] | ((uint16_t)dst[1] << 8) );
FUZZ_ASSERT(got == v, "u16_to_le failed to encode correctly");

// Validation: ensures non-null writable buffer with >=2 bytes and checks bytes written.

// Need 4 writable bytes
std::string buf = FUZZ_PARAM_STR();
size_t need = 4; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(uint32_t) % (buf.size() - need + 1));

uint32_t v = *FUZZ_PARAM(uint32_t);
uint8_t *dst = reinterpret_cast<uint8_t*>(buf.data()) + off;

u32_to_le(v, dst);

uint32_t got = (uint32_t)dst[0]
             | ((uint32_t)dst[1] << 8)
             | ((uint32_t)dst[2] << 16)
             | ((uint32_t)dst[3] << 24);
FUZZ_ASSERT(got == v, "u32_to_le failed to encode correctly");

// Validation: buffer size/offset enforced; verifies exact encoding.

// Need 8 writable bytes
std::string buf = FUZZ_PARAM_STR();
size_t need = 8; if (buf.size() < need) buf.resize(need, '\0');
size_t off = (size_t)(*FUZZ_PARAM(uint32_t) % (buf.size() - need + 1));

uint64_t v = *FUZZ_PARAM(uint64_t);
uint8_t *dst = reinterpret_cast<uint8_t*>(buf.data()) + off;

u64_to_le(v, dst);

uint64_t got = 0;
for (int i = 0; i < 8; ++i) got |= ((uint64_t)dst[i]) << (8*i);
FUZZ_ASSERT(got == v, "u64_to_le failed to encode correctly");

// Validation: enforces writable 8-byte region and asserts round-trip bits.

// Need 1 byte
std::string buf = FUZZ_PARAM_STR();
if (buf.size() < 1) buf.resize(1, '\0');
size_t off = (size_t)(*FUZZ_PARAM(unsigned int) % buf.size());

// Choose a random int8_t bit pattern and store its raw byte
int8_t v = (int8_t)(*FUZZ_PARAM(int));
reinterpret_cast<uint8_t*>(buf.data())[off] = (uint8_t)v; // same bits

const uint8_t *p = reinterpret_cast<const uint8_t*>(buf.data()) + off;
