import random
import string
from typing import List
import struct

# Generator for UTF-8/ASCII text fuzzers with filenames and numeric pools
# Produces a buffer <=4096 bytes with many NUL-terminated strings followed by
# binary scalars (u32/i32/double) commonly consumed by stubs.

MAX_SIZE = 4096

def _rand_alpha(r: random.Random, nmin=1, nmax=24) -> str:
    n = r.randint(nmin, nmax)
    return ''.join(r.choice(string.ascii_letters) for _ in range(n))

def _rand_token(r: random.Random, nmin=1, nmax=24, extra: str = "-_./:+") -> str:
    alphabet = string.ascii_letters + string.digits + extra
    n = r.randint(nmin, nmax)
    return ''.join(r.choice(alphabet) for _ in range(n))

def _rand_context(r: random.Random) -> str:
    choices = [
        "io", "bgzf", "vcf", "bcf", "bam", "thread", "hts", "index", "filter", "expr"
    ]
    return r.choice(choices)

def _rand_filename(r: random.Random) -> str:
    exts = [".sam", ".bam", ".cram", ".vcf", ".bcf", ".fa", ".fasta", ".fastq", ".tbi", ".csi", ".gzi"]
    base = _rand_token(r, 1, 10)
    prefix_opts = ["", "./", "/tmp/", "mem:", "data:"]
    pre = r.choice(prefix_opts)
    ext = r.choice(exts)
    return pre + base + ext

def _rand_vcf_header(r: random.Random) -> str:
    vn_major = r.choice([1,2,3,4])
    vn_minor = r.randint(0, 6)
    sn = _rand_token(r, 3, 8)
    ln = r.randint(100, 100000)
    lines = [
        f"##fileformat=VCFv{vn_major}.{vn_minor}",
        f"##INFO=<ID=FZ,Number=1,Type=Integer,Description=\"Fuzz\">",
        f"##FILTER=<ID=LowQual,Description=\"Low quality\">",
        f"#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO",
        f"{sn}\t1\trs1\tA\tC\t60\tPASS\tFZ=1",
    ]
    return "\n".join(lines)

def _rand_sam_header(r: random.Random) -> str:
    vn_major = r.choice([1,2])
    vn_minor = r.randint(0,6)
    sn = _rand_token(r, 3, 8)
    ln = r.randint(100, 100000)
    return f"@HD\tVN:{vn_major}.{vn_minor}\n@SQ\tSN:{sn}\tLN:{ln}\n"

def _rand_region_list(r: random.Random) -> str:
    items: List[str] = []
    for _ in range(r.randint(2,5)):
        chrom = r.choice(["chr1","chr2","chrX","chrY", _rand_token(r,3,6)])
        mode = r.randint(0,3)
        if mode == 0:
            items.append(chrom)
        elif mode == 1:
            pos = r.randint(1, 100000)
            items.append(f"{chrom}:{pos}")
        elif mode == 2:
            a = r.randint(1, 200000)
            b = a + r.randint(0, 10000)
            items.append(f"{chrom}:{a}-{b}")
        else:
            a = r.randint(1, 200000)
            items.append(f"{chrom}:{a}-")
    return "\n".join(items) + "\n"

def _rand_text(r: random.Random, nmin=0, nmax=128) -> str:
    n = r.randint(nmin, nmax)
    alphabet = string.ascii_letters + string.digits + string.punctuation + " \t"
    return ''.join(r.choice(alphabet) for _ in range(n))

def _pack_u32(x: int) -> bytes:
    return int(x & 0xFFFFFFFF).to_bytes(4, 'little', signed=False)

def _pack_i32(x: int) -> bytes:
    # Ensure representable as signed 32-bit little endian
    # Clamp into range -2^31..2^31-1 to avoid OverflowError
    if x < -0x80000000:
        x = -0x80000000
    if x > 0x7FFFFFFF:
        x = 0x7FFFFFFF
    return int(x).to_bytes(4, 'little', signed=True)

def _pack_double(d: float) -> bytes:
    return struct.pack('<d', d)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    out = bytearray()

    # String segments
    segments: List[str] = []
    segments.append(_rand_context(r))
    for _ in range(4):
        segments.append(_rand_text(r, 0, 64))
    for _ in range(4):
        segments.append(_rand_filename(r))
    segments.append(_rand_vcf_header(r))
    segments.append(_rand_sam_header(r))
    segments.append(_rand_region_list(r))
    for _ in range(6):
        segments.append(_rand_token(r, 1, 12))

    for s in segments:
        data = s.encode('utf-8', errors='replace') + b"\x00"
        if len(out) + len(data) > MAX_SIZE:
            break
        out += data

    # Append binary unsigned ints
    nums_u32 = [0, 1, 2, 3, 4, 5, 10, 16, 31, 63, 127, 255, 256, 512, 1024,
                2048, 4096, 10000, 65535, 100000, 0x7FFFFFFF, 0xFFFFFFFF]
    r.shuffle(nums_u32)
    for v in nums_u32[:16]:
        if len(out) + 4 > MAX_SIZE:
            break
        out += _pack_u32(v)

    # Append binary signed ints (safe range only)
    nums_i32 = [0, -1, 1, -10, 10, -1000, 1000, -2**31 + 1, 2**31 - 1, 50000000, -50000000]
    r.shuffle(nums_i32)
    for v in nums_i32[:8]:
        if len(out) + 4 > MAX_SIZE:
            break
        out += _pack_i32(v)

    # Append doubles including special values
    doubles = [0.0, 1.0, -1.0, 3.14159, -2.71828, 1e-6, 1e6, float('inf'), float('-inf')]
    for d in doubles:
        if len(out) + 8 > MAX_SIZE:
            break
        out += _pack_double(d)
    # Add a quiet NaN pattern if space
    if len(out) + 8 <= MAX_SIZE:
        out += struct.pack('<Q', 0x7ff8000000000000)

    return bytes(out[:MAX_SIZE])

import random
import string
from typing import List

# Target data type: VCF allele string
# Fuzzer stub builds a vector<string> of 1..4 alleles using FUZZ_PARAM_STR(),
# sanitizes by replacing newlines/commas with 'A' and enforcing non-empty (N),
# and truncates each to 16 chars. Our buffer should contain concatenated
# candidate allele strings separated in a way the harness understands. FUZZ
# framework typically slices bytes for successive FUZZ_PARAM_STR() calls.
# We'll emit a compact, structured sequence that encodes 1..4 alleles with
# realistic and diverse VCF allele tokens, staying within 4096 bytes.

# We craft alleles covering: single-base SNVs, multi-base REF/ALT, insertions
# ("A"->"AT"-like), deletions ("AT"->"A"-like), ambiguous Ns, symbolic tokens
# (<DEL>, <INS>, <DUP>, <INV>, <CNV>), breakend-like forms (A]chr1:100]) but
# without commas/newlines and length <= 16.

BASES = "ACGT"
AMBIG = "N"
SYMBOLICS = [
    "<DEL>", "<INS>", "<DUP>", "<INV>", "<CNV>", "<DUP:TANDEM>", "<INS:ME>"
]
# Breakend-like patterns (keep short, valid chars for stub; no commas/newlines)
BND_TEMPLATES = [
    "A]chr1:100]", "[chr2:200[A", "]chrX:123]G", "T[chrM:42["
]

def _rand_bases(rng: random.Random, min_len: int, max_len: int) -> str:
    L = rng.randint(min_len, max_len)
    return ''.join(rng.choice(BASES) for _ in range(L))

def _mutate_ins(ref: str, rng: random.Random) -> str:
    # Insert 1-5 bases at a random position
    ins = _rand_bases(rng, 1, max(1, min(5, 16 - len(ref))))
    pos = rng.randrange(len(ref)+1)
    alt = ref[:pos] + ins + ref[pos:]
    return alt[:16] if alt else ref + ins

def _mutate_del(ref: str, rng: random.Random) -> str:
    if len(ref) <= 1:
        return ref  # cannot delete usefully
    a = rng.randrange(len(ref))
    b = rng.randrange(a+1, len(ref)+1)
    alt = ref[:a] + ref[b:]
    return alt if alt else AMBIG

def _random_symbolic(rng: random.Random) -> str:
    s = rng.choice(SYMBOLICS)
    # ensure <= 16
    return s[:16]

def _random_bnd(rng: random.Random) -> str:
    return rng.choice(BND_TEMPLATES)

def _random_allele(rng: random.Random) -> str:
    choice = rng.randint(0, 7)
    if choice == 0:
        return rng.choice(BASES)
    if choice == 1:
        return _rand_bases(rng, 2, 16)
    if choice == 2:
        ref = _rand_bases(rng, 1, 8)
        return _mutate_ins(ref, rng)
    if choice == 3:
        ref = _rand_bases(rng, 2, 12)
        return _mutate_del(ref, rng)
    if choice == 4:
        # homopolymer
        b = rng.choice(BASES)
        return b * rng.randint(1, 16)
    if choice == 5:
        # ambiguous N or mix
        L = rng.randint(1, 16)
        return ''.join(rng.choice(BASES + AMBIG) for _ in range(L))
    if choice == 6:
        return _random_symbolic(rng)
    # choice == 7
    return _random_bnd(rng)

def _sanitize(s: str) -> str:
    # Mirror fuzzer stub sanitation: replace commas/newlines with 'A', ensure non-empty, max 16
    t = s.replace('\n', 'A').replace('\r', 'A').replace(',', 'A')
    if not t:
        t = 'N'
    return t[:16]

def _encode_alleles(alleles: List[str]) -> bytes:
    # We will join alleles with null separators. FUZZ frameworks commonly split
    # strings on NULs or length-prefix; NULs are safe and unambiguous and won't
    # be altered by the stub (it reads raw bytes into std::string).
    # To add more structure, we prefix with a small header indicating count.
    # Format:
    #   1 byte: count (1..4)
    #   repeated: [1 byte length][bytes]
    # length is the number of bytes of the allele string (<=16), enabling
    # deterministic parsing by harnesses that read sequentially.
    out = bytearray()
    out.append(len(alleles))
    for a in alleles:
        b = a.encode('ascii', 'ignore')[:16]
        if len(b) == 0:
            b = b'N'
        out.append(len(b))
        out.extend(b)
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    nals = rng.randint(1, 4)
    alleles: List[str] = []
    # Ensure first allele looks like a plausible REF (A/C/G/T/N block)
    first_len = rng.randint(1, 12)
    ref = ''.join(rng.choice(BASES + AMBIG) for _ in range(first_len))
    alleles.append(_sanitize(ref))
    for _ in range(nals - 1):
        # diversify ALT types with a mix of SNV, MNV, indel, symbolic, BND
        alt = _random_allele(rng)
        alleles.append(_sanitize(alt))
    # Encode in a compact custom TLV format as described above
    buf = _encode_alleles(alleles)
    # Keep well under 4096 bytes
    return buf[:4096]

import random
import string
from typing import List

# Generator for a valid VCF allele list string: REF[,ALT...]
# Constraints from stub:
# - Caller will truncate each FUZZ_PARAM_STR() to 12 chars and replace newlines/CR/commas
# - Empty REF becomes "N" and empty ALT becomes "A" in stub, but we still generate valid bases
# - nalt is chosen by the fuzzer (0..2), but we can pack multiple candidate allele lists so that
#   different FUZZ_PARAM_STR() calls read different slices from our buffer.
# Strategy:
# - Construct multiple comma-separated allele lists (with 1–3 alleles) and join them with NULs.
# - The fuzzer stub calls FUZZ_PARAM_STR() multiple times; typical harnesses read sequential
#   strings from the same input buffer. Supplying several NUL-terminated strings increases
#   chances each call receives a meaningful allele token.
# - Ensure alleles contain only A,C,G,T,N and small indel-style alleles to exercise behavior.

DNA = "ACGTN"

def rand_base(rng: random.Random) -> str:
    return rng.choice(DNA)

def rand_homopolymer(rng: random.Random, base: str = None, min_len: int = 1, max_len: int = 12) -> str:
    if base is None:
        base = rand_base(rng)
    l = rng.randint(min_len, max_len)
    return base * l

def rand_allele(rng: random.Random) -> str:
    # Produce a mix of SNPs and short indels/substitutions, max 12 chars (stub truncates anyway)
    kind = rng.choices(["snp","mnp","ins","del","poly"], weights=[40,10,20,15,15], k=1)[0]
    if kind == "snp":
        return rand_base(rng)
    if kind == "mnp":
        l = rng.randint(2, 5)
        return ''.join(rand_base(rng) for _ in range(l))
    if kind == "ins":
        # insertion-like ALT (longer string). REF provided separately
        l = rng.randint(2, 8)
        return ''.join(rand_base(rng) for _ in range(l))
    if kind == "del":
        # deletion-like REF longer; ALT could be single base
        return rand_base(rng)
    # homopolymer
    return rand_homopolymer(rng, None, 2, 10)

def rand_ref(rng: random.Random) -> str:
    # REF allele: at least one base, up to 12
    # Include some edge cases: N, long homopolymers, and mixed sequence
    choice = rng.randint(0, 4)
    if choice == 0:
        return "N"
    if choice == 1:
        return rand_homopolymer(rng)
    if choice == 2:
        l = rng.randint(1, 12)
        return ''.join(rand_base(rng) for _ in range(l))
    if choice == 3:
        # Common REF length 1
        return rand_base(rng)
    # Mixed with leading/trailing valid chars
    core = ''.join(rand_base(rng) for _ in range(rng.randint(2, 8)))
    return core

def make_allele_list(rng: random.Random, n_alt: int) -> str:
    ref = rand_ref(rng)
    alts: List[str] = []
    for _ in range(n_alt):
        alt = rand_allele(rng)
        # Ensure ALT differs from REF when plausible to exercise updates
        if alt == ref:
            # tweak one base
            pos = rng.randrange(len(alt))
            choices = [b for b in DNA if b != alt[pos]]
            alt = alt[:pos] + rng.choice(choices) + alt[pos+1:]
        alts.append(alt)
    return ",".join([ref] + alts)

def build_corpus(rng: random.Random) -> bytes:
    items: List[str] = []
    # A small suite with varying numbers of ALTs
    counts = [0,1,2,3]
    for n in counts:
        # cap n to 3 to keep short; stub itself limits to 0..2 ALTs for its chosen call
        n_alts = max(0, min(3, n))
        # generate multiple variants per count to provide many options
        for _ in range(3):
            items.append(make_allele_list(rng, n_alts))
    # Add some specific canonical cases
    items.extend([
        "A",            # single-base REF only
        "A,C",          # SNP
        "G,GA",         # insertion-like
        "TTT,T",        # deletion-like
        "N,A",          # ambiguous REF
        "ACGT,ACGA,ACGTN"  # mixed lengths, multiple ALTs
    ])
    # Join as NUL-terminated strings so multiple FUZZ_PARAM_STR() pulls can succeed
    blob = b"\x00".join(s.encode('ascii') for s in items) + b"\x00"
    # Ensure max size limit
    return blob[:4096]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return build_corpus(rng)
